 static byte[] zip(Map<String,String> m)throws Exception{ByteArrayOutputStream o=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(o)){for(Map.Entry<String,String> e:m.entrySet()){z.putNextEntry(new ZipEntry(e.getKey()));z.write(e.getValue().getBytes(StandardCharsets.UTF_8));z.closeEntry();}}return o.toByteArray();}
